CREATE TABLE IF NOT EXISTS music_submissions (id TEXT PRIMARY KEY, created_at TEXT NOT NULL, submission_type TEXT NOT NULL, artist TEXT NOT NULL, contact_email TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', genre TEXT NOT NULL, release_title TEXT NOT NULL, release_type TEXT NOT NULL DEFAULT '', release_date TEXT NOT NULL DEFAULT '', artwork_url TEXT NOT NULL DEFAULT '', official_audio_url TEXT NOT NULL, official_video_url TEXT NOT NULL DEFAULT '', streaming_url TEXT NOT NULL DEFAULT '', artist_page_url TEXT NOT NULL DEFAULT '', bio TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', rights_confirmed INTEGER NOT NULL DEFAULT 0, review_requested INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'new');
CREATE INDEX IF NOT EXISTS idx_music_submissions_created_at ON music_submissions(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_music_submissions_status ON music_submissions(status);
